      let t = null, long = false;
      const id = el.dataset.e;
      el.addEventListener("pointerdown", () => { long = false; if (el.dataset.act === "popup" || el.dataset.act === "close") return; t = setTimeout(() => { long = true; if (id) this._moreInfo(id); }, 550); });
