    for (const f of c.fridge) { const v = this.num(f.entity); if (f.max !== undefined && v !== null && v > f.max) out.push({ i: "mdi:fridge-alert", t: this.t("{n} trop chaud · {v}°", { n: f.name, v: this.f1(v) }), e: f.entity }); }
