    const gn = c.lights_off.length || c.cover ? `<div class="panel goodnight tap" data-act="goodnight" data-confirm="${this.esc(this.t("Éteindre + fermer ?"))}">${this.esc(this.t("Bonne nuit"))}</div>` : "";
